WITH sample AS (SELECT * EXCEPT (_sf_sample_hash) FROM (SELECT t.*, (xxhash64(to_json(struct(*))) & 9223372036854775807) AS _sf_sample_hash FROM `fake_project`.`dataset`.`orders` AS t) WHERE MOD(_sf_sample_hash, 10) < 1 LIMIT 100000) SELECT child.`customer_id` FROM sample AS child LEFT JOIN `fake_project`.`dataset`.`customers` AS parent ON child.`customer_id` = parent.`id` WHERE child.`customer_id` IS NOT NULL AND parent.`id` IS NULL